#ifndef SIMUL_PI_H
#define SIMUL_PI_H
//! This may not be included before windows.h or gl.h as it defines as a constant
//! something that these headers use as a variable name!
#define pi (3.1415926536f)
#define Pi pi
#define pi_double (3.1415926535897932384626433832795)
#define pi_over_180 (3.1415926535897932384626433832795/180.0)
#define rad_to_deg (180.0/3.1415926535897932384626433832795)
#endif

